  "answer": {
    "kind": "student",
    "resposta": "",
    "raciocinio": "1. Causa raiz:
O código original usa fetch() sem AbortController, deixando a requisição pendente
por tempo ilimitado quando a API fica lenta. Além disso, não verifica response.ok:
em JavaScript, fetch não lança erro para HTTP 4xx/5xx — o código prosseguia para
response.json() em qualquer status, e se o corpo de erro não contivesse
rates[toCurrency], gerava TypeError: Cannot read properties of undefined, que é
exatamente a mensagem observada nos logs de produção.

2. Timeout configurado com AbortController por tentativa:
Uso AbortController + clearTimeout em fetchWithTimeout. O timer é criado antes de
cada chamada fetch e cancelado no bloco finally após a resposta, garantindo que
não vaze entre tentativas. O erro AbortError é capturado e convertido em mensagem
descritiva: "Exchange rate API timeout after 3000ms".

3. Tratamento de falhas:
- HTTP 4xx: erro permanente (moeda inválida, chave expirada); propagado
  imediatamente sem retry.
- HTTP 5xx: erro transitório; armazenado em lastError e o loop continua para
  a próxima tentativa.
- JSON inválido: erro permanente de contrato da API; propagado sem retry.
- Ausência de rates[toCurrency]: erro de contrato; propagado sem retry.
Em nenhum caso a função retorna undefined, null ou NaN.

4. Estratégia de retry:
O loop for itera de 0 a MAX_RETRIES (inclusive), totalizando no máximo 2
tentativas. O retry só ocorre para timeout, erro de rede e HTTP 5xx. Erros
permanentes são lançados diretamente. Após esgotar as tentativas, o último
erro é relançado com mensagem descritiva.

5. Trade-offs:
- Latência adicional: no pior caso, 2 timeouts de 3s cada resultam em até 6s
  de espera antes do erro final.
- Idempotência: GET de cotação é seguro para retry — sem efeito colateral.
- Retry agressivo: limite fixo de 1 tentativa evita amplificação de carga
  em cascata durante degradação da API. Circuit breaker ou cache de última
  cotação seriam opções para cenários de degradação prolongada.
",
    "codigo": "// exchange-rate.js

const API_BASE_URL = 'https://api.exchangerates.example.com';
const TIMEOUT_MS  = 3000;
const MAX_RETRIES = 1;

async function fetchWithTimeout(url, timeoutMs) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, { signal: controller.signal });
    return response;
  } finally {
    clearTimeout(timer);
  }
}

async function getExchangeRate(fromCurrency, toCurrency) {
  const url = `${API_BASE_URL}/latest?base=${fromCurrency}&symbols=${toCurrency}`;
  let lastError;

  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    try {
      const response = await fetchWithTimeout(url, TIMEOUT_MS);

      // Erro permanente: não realiza retry
      if (response.status >= 400 && response.status < 500) {
        throw new Error(
          `Exchange rate API client error: HTTP ${response.status} for ${fromCurrency}/${toCurrency}`
        );
      }

      // Erro transitório: armazena para possível retry
      if (!response.ok) {
        lastError = new Error(
          `Exchange rate API server error: HTTP ${response.status}`
        );
        continue;
      }

      let data;
      try {
        data = await response.json();
      } catch {
        throw new Error('Exchange rate API returned invalid JSON');
      }

      const rate = data?.rates?.[toCurrency];
      if (typeof rate !== 'number' || isNaN(rate)) {
        throw new Error(
          `Exchange rate API response missing rate for ${toCurrency}`
        );
      }

      return rate;

    } catch (err) {
      // Erros permanentes (4xx, JSON inválido, taxa ausente) são propagados imediatamente
      if (
        err.message.includes('client error') ||
        err.message.includes('invalid JSON') ||
        err.message.includes('missing rate')
      ) {
        throw err;
      }

      // Timeout ou erro de rede: elegível a retry
      lastError = err.name === 'AbortError'
        ? new Error(`Exchange rate API timeout after ${TIMEOUT_MS}ms`)
        : err;
    }
  }

  throw lastError ?? new Error('Exchange rate API failed after retries');
}

module.exports = { getExchangeRate, TIMEOUT_MS, MAX_RETRIES };
